const subscriberId = $('Criar contato no many').item.json.data.id;
const webhookData = $('Webhook').item.json.body;

const campos = [
  {
    subscriber_id: subscriberId,
    field_id: 13909540,
    field_value: webhookData.product.offer.title || "sem título"
  },
  {
    subscriber_id: subscriberId,
    field_id: 13909541,
    field_value: String(webhookData.product.offer.price || "0")
  },
  {
    subscriber_id: subscriberId,
    field_id: 13911451,
    field_value: webhookData.eventStatus || "pendente"
  },
  {
    subscriber_id: subscriberId,
    field_id: 13911452,
    field_value: webhookData.shipping.shippingCode || "vazio"
  }
];

return campos.map(campo => ({
  json: campo
}));

